/* ===== v0.4: Backend (gemeinsame Datenbank), Google Drive, Claude, neue Module ===== */
const BK = { mode: "local", status: "Lokal im Browser", db: null, user: null, canEdit: null, mcp: null, sample: null, events: [], control: [], queue: Promise.resolve(), timer: null, replayT: null };
const newTs = () => Date.now() * 1000 + Math.floor(Math.random() * 1000);
function startBackend() {
  if (!window.claude || !window.claude.use) return;
  claude.use("user").then(async u => { BK.user = u; if (u) { try { BK.canEdit = (await u.canEdit()) === true; } catch (e) { BK.canEdit = false; } try { BK.canWrite = await u.can("data.write"); } catch (e) { BK.canWrite = null; } } await resolveOwner(); adoptAccounts(); render(); }).catch(() => {});
  claude.use("sample").then(s => { BK.sample = s; render(); }).catch(() => {});
  claude.use("mcp").then(m => { BK.mcp = m; render(); }).catch(() => {});
  claude.use("db").then(db => {
    if (!db) { BK.status = "Lokal im Browser (gemeinsame Datenbank in dieser Ansicht nicht verfügbar)"; render(); return; }
    BK.db = db; BK.status = "Verbinde mit gemeinsamer Datenbank …"; render();
    BK.timer = setTimeout(() => { BK.status = "Gemeinsame Datenbank noch nicht erreichbar – Anzeige ggf. veraltet"; render(); }, 10000);
    const onErr = e => { clearTimeout(BK.timer); BK.mode = "local"; BK.status = "Gemeinsame Datenbank nicht erreichbar (" + e.code + ") – lokal weiter"; render(); };
    db.collection("events").orderBy("ts").onSnapshot(s => { BK.events = s.docs.map(d => Object.assign({ _id: d.id }, d.data())); if (!s.metadata.fromCache) { clearTimeout(BK.timer); BK.mode = "db"; BK.status = "Gemeinsame Datenbank · live für alle Betrachter"; } scheduleReplay(); }, onErr);
    db.collection("control").orderBy("ts").onSnapshot(s => { BK.control = s.docs.map(d => Object.assign({ _id: d.id }, d.data())); scheduleReplay(); }, onErr);
  }).catch(() => {});
}
function scheduleReplay() { clearTimeout(BK.replayT); BK.replayT = setTimeout(replayFromBackend, 120); }
function replayFromBackend() {
  const all = BK.events.map(e => Object.assign({ kind: "event" }, e)).concat(BK.control.map(c => Object.assign({ kind: "control" }, c))).sort((a, b) => a.ts - b.ts);
  let size = "S"; for (const c of BK.control) if (c.size) size = c.size;
  if (size !== S.size) { S.size = size; captureBase(); }
  W = E.createWorld({ size: S.size });
  for (const x of all) { try { if (x.kind === "control") { if (x.reset) E.resetTenant(W, x.reset); else if (x.resetAll || x.size) E.resetAll(W); else if (x.restore) { /* Wiederherstellung: Ereignisse folgen einzeln */ } } else E.dispatch(W, x.t, x.cmd, x.p, x.ctx); } catch (e) {} }
  render();
}
function persist(entry) {
  if (BK.mode === "db" && BK.db) { const doc = Object.assign({ ts: newTs(), at: new Date().toISOString() }, entry); const col = entry.cmd ? "events" : "control";
    BK.queue = BK.queue.then(() => BK.db.collection(col).doc().set(JSON.parse(JSON.stringify(doc)))).catch(e => { toast(e.code === "invalid_argument" ? (col === "control" ? "Nur Editoren dürfen Demo-Unternehmen zurücksetzen." : "Du hast auf dieser Seite nur Leserechte. Bitte den Inhaber, dir Mitwirkungsrechte zu geben.") : "Speichern fehlgeschlagen: " + (e.code || "unbekannt"), true); replayFromBackend(); }); return true; }
  return false;
}
async function pruneBackend() { if (!(BK.mode === "db" && BK.db)) return; const lastAll = BK.control.filter(c => c.resetAll || c.size).slice(-1)[0]; if (!lastAll) return toast("Erst „Alle zurücksetzen“ – danach sind ältere Ereignisse ohne Wirkung und können entfernt werden.", true);
  for (const e of BK.events.filter(x => x.ts < lastAll.ts)) { try { await BK.db.doc("events/" + e._id).delete(); } catch (x) { break; } }
  for (const c of BK.control.filter(x => x.ts < lastAll.ts)) { try { await BK.db.doc("control/" + c._id).delete(); } catch (x) { break; } } }
const isAdmin = () => BK.mode === "db" ? BK.canEdit === true : S.admin;

/* ---------- Google Drive: Sicherung, Export, Wiederherstellung ---------- */
const GD = "Google Drive";
function gdErr(e) { const m = { server_not_connected: "Google Drive ist nicht verbunden. In claude.ai unter Einstellungen → Konnektoren hinzufügen.", needs_reauth: "Google Drive neu verbinden (claude.ai → Einstellungen → Konnektoren).", not_in_manifest: "Google Drive ist für diese Seite nicht erlaubt.", approval_required: "Der Zugriff auf Google Drive braucht deine Freigabe. Die Seite in claude.ai öffnen und erlauben.", selection_required: "Bitte in claude.ai auswählen, welches Google-Drive-Konto genutzt wird.", tool_error: "Google Drive meldet einen Fehler: " + (e && e.message || ""), server_unavailable: "Google Drive ist gerade nicht erreichbar. Später erneut versuchen." }; return m[e && e.code] || "Google Drive: " + ((e && e.message) || "unbekannter Fehler"); }
function currentLog() { return BK.mode === "db" ? BK.control.map(c => Object.assign({ kind: "control" }, c)).concat(BK.events.map(e => Object.assign({ kind: "event" }, e))).sort((a, b) => a.ts - b.ts).map(({ _id, ...r }) => r) : LOG; }
async function gdBackup() {
  if (!BK.mcp) return toast("Google Drive ist in dieser Ansicht nicht verfügbar.", true); S.gd = { busy: "Sicherung wird erstellt …" }; render();
  const body = JSON.stringify({ app: "STEGARC Suite", version: E.VERSION, seed: W.seed, size: S.size, createdAt: new Date().toISOString(), log: currentLog(), fingerprints: Object.fromEntries(E.TENANT_IDS.map(id => [id, E.tenantHash(W.tenants[id])])) });
  try { const r = await BK.mcp.callTool(GD, "create_file", { title: "STEGARC Sicherung " + new Date().toLocaleString("de-DE").replace(/[/:]/g, "-"), textContent: body, contentMimeType: "text/plain", disableConversionToGoogleType: true }); const f = r.payload || {}; S.gd = { ok: `Sicherung in Google Drive erstellt (${(f.title || f.name || "Datei")}, ${currentLog().length} Ereignisse).`, link: f.alternateLink || f.webViewLink || f.url || null }; }
  catch (e) { S.gd = { err: gdErr(e) }; } render();
}
async function gdExportJournal() {
  if (!BK.mcp) return toast("Google Drive ist in dieser Ansicht nicht verfügbar.", true); const t = T(); S.gd = { busy: "Belegjournal wird exportiert …" }; render();
  const rows = [["Beleg", "Datum", "Periode", "Text", "Konto", "Kontobezeichnung", "Soll", "Haben", "Benutzer"]]; for (const d of t.docs) for (const l of d.lines) rows.push([d.no, d.date, d.period, d.text, l.acct, E.COA[l.acct][0], String(l.dr).replace(".", ","), String(l.cr).replace(".", ","), d.user]);
  const csv = rows.map(r => r.map(c => '"' + String(c).replace(/"/g, '""') + '"').join(";")).join("\n");
  try { const r = await BK.mcp.callTool(GD, "create_file", { title: "STEGARC Belegjournal " + T_NAMES[t.id] + " " + dDe(t.date), textContent: csv, contentMimeType: "text/csv" }); const f = r.payload || {}; S.gd = { ok: `Belegjournal ${T_NAMES[t.id]} als Google-Tabelle angelegt (${t.docs.length} Belege).`, link: f.alternateLink || f.webViewLink || f.url || null }; }
  catch (e) { S.gd = { err: gdErr(e) }; } render();
}
async function gdList() {
  if (!BK.mcp) return toast("Google Drive ist in dieser Ansicht nicht verfügbar.", true); S.gd = { busy: "Suche Sicherungen …" }; render();
  try { const r = await BK.mcp.callTool(GD, "search_files", { query: "title contains 'STEGARC Sicherung' and trashed = false", pageSize: 10, excludeContentSnippets: true }); const p = r.payload || {}; const files = (p.files || p.results || p.items || (Array.isArray(p) ? p : [])).map(f => ({ id: f.id || f.fileId, title: f.title || f.name, modified: f.modifiedTime || f.modifiedDate || "" })).filter(f => f.id); S.gd = { files, ok: files.length ? null : "Keine Sicherung gefunden." }; }
  catch (e) { S.gd = { err: gdErr(e) }; } render();
}
async function gdRestore(fileId) {
  if (!isAdmin()) return toast("Nur Editoren dürfen wiederherstellen.", true); S.gd = { busy: "Sicherung wird gelesen …" }; render();
  try { const r = await BK.mcp.callTool(GD, "read_file_content", { fileId }); let txt = typeof r.payload === "string" ? r.payload : (r.payload && (r.payload.content || r.payload.text)) || (r.content || []).filter(c => c.type === "text").map(c => c.text).join("\n");
    const data = JSON.parse(txt.slice(txt.indexOf("{"), txt.lastIndexOf("}") + 1)); if (!Array.isArray(data.log)) throw { message: "Datei ist keine STEGARC-Sicherung." };
    // Wiederherstellung: neutraler Ausgangszustand, dann alle Ereignisse in Originalreihenfolge
    if (BK.mode === "db") { await BK.db.collection("control").doc().set({ ts: newTs(), resetAll: true, size: data.size || "S", restoredFrom: fileId }); let i = 0; for (const x of data.log) { const base = newTs() + (++i); if (x.kind === "control" || x.reset || x.resetAll) await BK.db.collection("control").doc().set(Object.assign({}, x, { ts: base })); else await BK.db.collection("events").doc().set(Object.assign({}, x, { ts: base })); } }
    else { S.size = data.size || "S"; W = E.createWorld({ size: S.size }); captureBase(); LOG = []; for (const x of data.log) { try { applyLog(x); LOG.push(x); } catch (e) {} } saveLog(); }
    S.gd = { ok: `Wiederhergestellt: ${data.log.length} Ereignisse. Fingerabdrücke werden neu berechnet.` }; S.restoreCheck = data.fingerprints || null;
  } catch (e) { S.gd = { err: e.code ? gdErr(e) : "Wiederherstellung fehlgeschlagen: " + (e.message || "Format nicht lesbar") }; } render();
}

/* ---------- Claude als KI-Assistent mit Werkzeugen auf die Engine ---------- */
