/* ---------- Nächste Aktionen für neue Prozesse ---------- */
const _nextAction = nextAction;
nextAction = function (tid, inst) {
  const o = inst.object; const a = inst.steps.find(s => s.state === "active");
  if (tid === "elevon" && inst.chain && /Service|Maintain/.test(inst.chain)) { if (!a) return null; if (a.name === "Techniker eingeplant") return { label: "Techniker einplanen", cmd: "scheduleTechnician", p: { svNo: o.no } }; if (a.name === "Ausführung") return { label: "Ausführung erfassen", cmd: "executeService", p: { svNo: o.no } }; if (a.name === "Abrechnung") return { label: "Abrechnen", cmd: "invoiceService", p: { svNo: o.no } }; return null; }
  if (tid === "elevon" && inst.id === "MIG-LN") { return a && a.name === "Testmigration" ? { label: "Testmigration", cmd: "migrationTest", p: {} } : null; }
  if (tid === "novamart" && inst.chain === "Returns") { if (!a) return null; return a.name === "Prüfung" ? { label: "Prüfen: wiederverkaufbar", cmd: "inspectReturn", p: { retNo: o.no, decision: "wiederverkaufbar" } } : a.name === "Gutschrift" ? { label: "Gutschrift", cmd: "creditReturn", p: { retNo: o.no } } : a.name === "Rückzahlung" ? { label: "Rückzahlung", cmd: "refundReturn", p: { retNo: o.no } } : null; }
  if (tid === "novamart" && inst.chain === "Click & Collect") { if (!a) return null; return a.name === "Bereitstellung" ? { label: "Bereitstellen", cmd: "prepareCollect", p: { orderNo: o.no } } : a.name === "Übergabe" ? { label: "An Kunden übergeben", cmd: "handoverCollect", p: { orderNo: o.no } } : a.name === "Rechnung" ? { label: "Rechnung", cmd: "invoiceWebOrder", p: { orderNo: o.no } } : a.name === "Zahlungsabgleich" ? { label: "Zahlung abgleichen", cmd: "settlePSP", p: { orderNo: o.no } } : null; }
  return _nextAction(tid, inst);
};

