/* ---------- KI-Assistent: Claude mit Engine-Werkzeugen, regelbasiert als Rückfall ---------- */
const _ask = ask;
ask = function (q) { if (!q || !q.trim()) return; if (BK.sample && S.aiMode !== "rules") askClaude(q.trim()); else _ask(q); };
VIEWS.ai = () => { const ch = S.chat[S.tenant]; const llm = BK.sample && S.aiMode !== "rules";
  return head("AI Assistant · " + esc(T_NAMES[S.tenant]), "KI-Assistent", BK.sample ? `<div class="seg"><button class="${llm ? "on" : ""}" data-act="aiMode" data-m="llm">Claude</button><button class="${!llm ? "on" : ""}" data-act="aiMode" data-m="rules">Regelbasiert</button></div>` : "")
  + statusNote(llm ? "live" : "proto", llm ? "Claude beantwortet Fragen in natürlicher Sprache und liest Zahlen ausschließlich über Werkzeuge direkt aus der Engine (Kennzahlen, GuV, Projekte, Nachschub, offene Posten, Prozesse, Fertigung, Migration). Claude bucht nichts und gibt nichts frei. Jede Antwort nennt Datenbasis, Zeitraum und Berechnung." : "Die Antworten werden regelbasiert aus den aktuellen Daten berechnet und zeigen Datenbasis, Zeitraum und Rechenweg." + (BK.sample ? "" : " Claude ist in dieser Ansicht nicht verfügbar."))
  + `<section class="card" style="display:flex;flex-direction:column"><div class="ai-body" id="aiBody" style="min-height:320px">${ch.length ? ch.map(m => m.u ? `<div class="msg u">${esc(m.u)}</div>` : `<div class="msg a">${m.a}</div>`).join("") : `<div style="display:flex;flex-direction:column;gap:8px">${AI_SUGG.concat(["Welche Wartungen sind bei Elevon fällig?", "Wie ist der Stand der Migration Liftservice Nord?"]).map(q => `<button class="qcard" data-act="ask" data-q="${esc(q)}">${ic("ai", 18)}<span>${esc(q)}</span></button>`).join("")}</div>`}</div><form class="ai-f" data-form="chat"><div class="composer"><input id="chatIn" placeholder="Frage stellen oder Aufgabe beschreiben …" aria-label="Frage an den KI-Assistenten"><div class="tools">${S.aiCtl ? `<button type="button" class="btn sm" data-act="aiStop">Stopp</button>` : ""}${ch.length ? `<button type="button" class="btn sm" data-act="clearChat">Neu</button>` : ""}<button class="send" type="submit" aria-label="Senden">${ic("send", 17)}</button></div></div></form></section>`; };

/* ---------- Demo Control Center: Backend, Rechte, Google Drive ---------- */
const _admin = VIEWS.admin;
VIEWS.admin = () => {
  if (BK.mode === "db" && BK.canEdit !== true) return `<div class="lock card card-pad">${ic("shield", 34)}<h2>Demo Control Center</h2><p class="muted">Zurücksetzen, Datenmenge und Wiederherstellung sind Editoren dieser Seite vorbehalten. Du kannst alle Demos ausführen; die Daten werden mit allen Betrachtern geteilt.</p></div>`;
  if (BK.mode === "db") S.admin = true;
  const gd = S.gd || {};
  return _admin().replace(/<button class="btn" data-act="lockAdmin">Sperren<\/button>/, BK.mode === "db" ? "" : '<button class="btn" data-act="lockAdmin">Sperren</button>')
   + `<div class="grid g2"><section class="card card-pad" style="display:flex;flex-direction:column;gap:10px"><h3>Backend</h3><div class="kv"><span>Speicher</span><span>${esc(BK.status)}</span><span>Ereignisse</span><span>${BK.mode === "db" ? num(BK.events.length) + " gemeinsam gespeichert" : num(LOG.length) + " in diesem Browser"}</span><span>Rechte</span><span>${BK.mode === "db" ? (BK.canEdit ? "Editor: darf zurücksetzen und wiederherstellen" : "Mitwirkende: dürfen Vorgänge ausführen") : "Bedienschutz per PIN"}</span><span>KI</span><span>${BK.sample ? "Claude mit Engine-Werkzeugen" : "regelbasiert"}</span></div><p class="small faint">Die Welt wird bei jedem Öffnen aus Seed und Ereignisprotokoll neu berechnet. Darum ist jede Demo reproduzierbar und für alle Betrachter identisch.</p>${BK.mode === "db" ? `<div><button class="btn sm" data-act="prune">Protokoll leeren (nach „Alle zurücksetzen“)</button></div>` : ""}</section>
    <section class="card card-pad" style="display:flex;flex-direction:column;gap:10px"><h3>Google Drive</h3><p class="small muted">Sicherung des Ereignisprotokolls als Datei, Export des Belegjournals als Google-Tabelle, Wiederherstellung einer Sicherung. Läuft mit deinem eigenen Google-Konto.</p>${BK.mcp ? `<div class="row"><button class="btn pri sm" data-act="gdBackup">Sicherung erstellen</button><button class="btn sm" data-act="gdExport">Belegjournal ${esc(T_NAMES[S.tenant].split(" ")[0])} exportieren</button><button class="btn sm" data-act="gdList">Sicherungen anzeigen</button></div>` : `<p class="small">Google Drive ist in dieser Ansicht nicht verfügbar.</p>`}
     ${gd.busy ? `<p class="small muted">${esc(gd.busy)}</p>` : ""}${gd.ok ? `<div class="note good small">${esc(gd.ok)}${gd.link ? ` <a href="${esc(gd.link)}" target="_blank" rel="noopener">Öffnen</a>` : ""}</div>` : ""}${gd.err ? `<div class="note warn small">${esc(gd.err)}</div>` : ""}
     ${gd.files ? `<div class="list">${gd.files.map(f => `<div class="li" style="padding:6px 0"><span class="grow small">${esc(f.title)}<span class="faint"> ${esc(String(f.modified).slice(0, 16).replace("T", " "))}</span></span><button class="btn sm" data-act="gdRestore" data-id="${esc(f.id)}">Wiederherstellen</button></div>`).join("")}</div>` : ""}
     ${S.restoreCheck ? `<p class="small">${E.TENANT_IDS.every(id => S.restoreCheck[id] === E.tenantHash(W.tenants[id])) ? pill("p-good", "Fingerabdrücke identisch mit der Sicherung") : pill("p-warn", "Fingerabdrücke werden abgeglichen …")}</p>` : ""}</section></div>`;
};
ACT.prune = async () => { toast("Protokoll wird geleert …"); await pruneBackend(); toast("Protokoll geleert."); };

